// Content is generated by scripts/import-content.mjs from content-source/.
// Edit the documents and run `npm run import`; don't edit src/content by hand.
import { defineCollection, reference } from 'astro:content';
import { file, glob } from 'astro/loaders';
import { z } from 'astro/zod';

const face = z.enum(['Oval', 'Round', 'Square', 'Long', 'Heart']);
const hairType = z.enum(['Straight', 'Wavy', 'Curly']);
const growth = z.enum(['Patchy', 'Medium', 'Full']);
const upkeep = z.enum(['Low', 'Medium', 'High']);
const text = z.string().min(1);

const faq = z.array(z.object({ q: text, a: text }));

const base = {
  slug: z.string().regex(/^[a-z0-9-]+$/),
  updated: z.coerce.date(),
  name: text,
  shortLine: text,
  description: text,
  pickIf: text,
  skipIf: text,
  daily: text,
  weekly: text,
  nextVisit: text,
  atShop: text.optional(),
  suitsText: text,
  alsoCalled: z.array(text),
  mainPhoto: z.enum(['front', 'side']),
  /** Labels for the image, drawn by the app so they can be translated. x and y place the dot, in % of the photo. */
  callouts: z.array(
    z.object({ title: text, text, x: z.number().min(0).max(100).optional(), y: z.number().min(0).max(100).optional() }),
  ),
};

const withSteps = {
  ...base,
  faq: faq.min(3),
  barberSteps: z.array(text).min(1),
  barberNote: text.optional(),
};

const hair = defineCollection({
  loader: file('src/content/hair.json'),
  schema: z.object({
    ...withSteps,
    length: text,
    upkeep,
    face: z.array(face).min(1),
    hairType: z.array(hairType).min(1),
    thinHairOk: z.boolean(),
  }),
});

const beards = defineCollection({
  loader: file('src/content/beards.json'),
  schema: z.object({
    ...withSteps,
    length: text,
    upkeep,
    face: z.array(face).min(1),
    growth: z.array(growth).min(1),
    /** separate: follows the Moustache slot. trimmed: empty slot means "trim to match". included: slot is locked. */
    moustacheMode: z.enum(['separate', 'trimmed', 'included']),
  }),
});

const moustaches = defineCollection({
  loader: file('src/content/moustaches.json'),
  schema: z.object({
    ...withSteps,
    length: text,
    upkeep,
    face: z.array(face).min(1),
    growth: z.array(growth).min(1),
  }),
});

const colours = defineCollection({
  loader: file('src/content/colours.json'),
  schema: z.object({
    ...withSteps,
    levelTone: text,
    coversGrey: text,
    bleach: text,
    skin: z.array(z.enum(['Light', 'Medium', 'Deep'])).min(1),
    grey: z.array(z.enum(['None', 'Some', 'Lots'])).min(1),
    timeAtShop: text,
    swatchLabel: text,
  }),
});

const looks = defineCollection({
  loader: file('src/content/looks.json'),
  schema: z.object({
    ...base,
    upkeep,
    face: z.array(face).min(1),
    growth: z.array(growth).min(1),
    hairType: z.array(hairType).min(1),
    thinHairOk: z.boolean(),
    hair: reference('hair'),
    beard: reference('beards').nullable(),
    moustache: reference('moustaches').nullable(),
    moustacheMode: z.enum(['no-change', 'shave-off', 'part-of-beard', 'style']),
    colour: reference('colours').nullable(),
    includesText: text,
  }),
});

const learn = defineCollection({
  loader: glob({ pattern: '*.md', base: './src/content/learn' }),
  schema: z.object({
    code: z.string().regex(/^P\d{2}$/),
    title: text,
    description: z.string().max(155),
    readMinutes: z.number().int().positive(),
    topic: z.enum(['Face shape', 'Haircuts', 'Beard', 'Colour', 'Care', 'Talk to your barber']),
    shortAnswer: text,
    fromTheChair: text,
    faq,
    /** Catalogue IDs such as H07 or B04, across categories. */
    related: z.array(z.string().regex(/^[HBMCL]\d{2}$/)),
    imageAlt: text,
    sources: z.array(text),
    updated: z.coerce.date(),
  }),
});

export const collections = { hair, beards, moustaches, colours, looks, learn };
